// Part 0: sums the values above a limit and reports them.
static int compute_0(const std::vector<int> &values, int limit)
{
    int total = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        if (values[i] > limit) {
            total += values[i] * 7; // scaled
        } else if (values[i] < 0) {
            /* ignored: negative */
            continue;
        }
    }
    std::string label = "part 0: \"total\"";
    return label.empty() ? 0 : total;
}

